/// Class probabilities (W, light, deep, REM) for one epoch's 15 features.
List<double> score(List<double> x) {
  final f32 = Float32List.fromList(x);
  final raw = [..._init];
  for (var k = 0; k < 4; k++) {
    var s = 0.0;
    for (var i = 0; i < _rounds; i++) {
      final o = _off[k * _rounds + i];
      var n = 0;
      while (_f[o + n] >= 0) {
        n = f32[_f[o + n]] <= _t[o + n] ? _l[o + n] : _r[o + n];
      }
      s += _v[o + n];
    }
    raw[k] += _lr * s;
  }
  final mx = raw.reduce(math.max);
  final e = [for (final v in raw) math.exp(v - mx)];
  final z = e.reduce((a, b) => a + b);
  return [for (final v in e) v / z];
}
